"use client"; import { useState } from "react"; import Link from "next/link"; import { useRouter } from "next/navigation"; import { supabase } from "@/lib/supabase"; import { Button } from "@/components/ui/button"; import { Input } from "@/components/ui/input"; import { Label } from "@/components/ui/label";
export default function Register(){const router=useRouter();const [name,setName]=useState("");const [email,setEmail]=useState("");const [pw,setPw]=useState("");const [pw2,setPw2]=useState("");const [err,setErr]=useState("");const [loading,setLoading]=useState(false);
 async function onSubmit(e:React.FormEvent){e.preventDefault();setErr("");if(pw.length<6){setErr("Password must be at least 6 characters.");return;}if(pw!==pw2){setErr("Passwords do not match.");return;}setLoading(true);const {error}=await supabase.auth.signUp({email,password:pw,options:{data:{full_name:name}}});setLoading(false);if(error){setErr(error.message);return;}router.replace("/app/dashboard");}
 return <div className="flex min-h-screen items-center justify-center bg-[#050807] px-4 text-zinc-100"><div className="w-full max-w-md rounded-lg border border-white/[0.08] bg-[#0F1511] p-7"><Link href="/" className="font-display font-semibold">ZEVQYN</Link><h1 className="mt-5 text-2xl font-semibold tracking-tight">Create your workspace</h1><p className="mt-1 text-sm text-zinc-400">Free to start. Your research stays private.</p><form onSubmit={onSubmit} className="mt-6 space-y-4"><div className="space-y-2"><Label htmlFor="name">Full name</Label><Input id="name" value={name} onChange={e=>setName(e.target.value)} required/></div><div className="space-y-2"><Label htmlFor="email">Email</Label><Input id="email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></div><div className="space-y-2"><Label htmlFor="pw">Password</Label><Input id="pw" type="password" value={pw} onChange={e=>setPw(e.target.value)} required autoComplete="new-password"/></div><div className="space-y-2"><Label htmlFor="pw2">Confirm password</Label><Input id="pw2" type="password" value={pw2} onChange={e=>setPw2(e.target.value)} required autoComplete="new-password"/></div>{err&&<p className="text-sm text-red-300" role="alert">{err}</p>}<Button type="submit" className="w-full" disabled={loading}>{loading?"Creating…":"Create account"}</Button></form><p className="mt-5 text-center text-sm text-zinc-400">Already have an account? <Link href="/login" className="text-indigo-300">Sign in</Link></p></div></div>;}
